async function startGame(){const promoMode=document.body.classList.contains('promo-mode');if(!promoMode)ensurePerfectAudio();if(!promoMode)ensureMusicAnalyser();song=selected();chart=await fetch(song.charts[diffs[di]]).then(r=>r.json());const promoParams=promoMode?new URLSearchParams(location.search):null,promoStart=promoMode?Math.max(0,Number(promoParams.get('start')??song.promoStart??0)||0):0,promoDuration=promoMode?Math.max(1,Number(promoParams.get('duration')??song.promoDuration??30)||30):0;currentRun={songId:song.id,difficultyId:diffs[di],autoPlay,finalized:false};gameEvents.runStart.forEach(listener=>listener(currentRun));preview.pause();audio.src=song.audio;const seekPromoStart=()=>{if(promoMode&&Math.abs(audio.currentTime-promoStart)>.05)audio.currentTime=Math.min(promoStart,Math.max(0,(Number.isFinite(audio.duration)?audio.duration-.05:promoStart)))};if(promoMode){if(audio.readyState>=1)seekPromoStart();else audio.addEventListener('loadedmetadata',seekPromoStart,{once:true})}else audio.currentTime=0;$('#work-title').textContent=song.title;$('#work-description').textContent=song.description||'';$('#work-artist').textContent=song.artist||'';$('#work-genre').textContent=song.genre||'';$('#work-bpm').textContent=`${song.bpm||'—'} BPM`;$('#difficulty').textContent=diffs[di].toUpperCase();const img=$('#background-image'),fallback=$('#media-fallback');img.hidden=!song.jacket;fallback.hidden=!!song.jacket;if(song.jacket)img.src=song.jacket;reset();show('play');beginCountdown(()=>{playing=true;const startPromoTimer=()=>{clearTimeout(startGame.promoTimer);startGame.promoTimer=setTimeout(()=>{if(!playing)return;playing=false;audio.pause();cancelAnimationFrame(raf);nodes.forEach(n=>n.remove());nodes.clear()},promoDuration*1000)},playNow=()=>audio.play().then(()=>{if(promoMode)startPromoTimer();render()});if(promoMode){const playAfterSeek=()=>{audio.removeEventListener('seeked',playAfterSeek);playNow().catch(handlePromoPlayError)};const handlePromoPlayError=error=>{playing=false;cancelAnimationFrame(raf);console.warn('PROMO audio autoplay was blocked.',error);const resume=()=>{document.removeEventListener('pointerdown',resume);document.removeEventListener('keydown',resume);playing=true;audio.addEventListener('seeked',()=>playNow().catch(()=>show('title')),{once:true});audio.currentTime=promoStart};document.addEventListener('pointerdown',resume,{once:true});document.addEventListener('keydown',resume,{once:true})};if(Math.abs(audio.currentTime-promoStart)<=.05)playNow().catch(handlePromoPlayError);else{audio.addEventListener('seeked',playAfterSeek,{once:true});audio.currentTime=promoStart}}else playNow().catch(()=>{playing=false;cancelAnimationFrame(raf);currentRun=null;show('title')})})}
function updateHpUI(effect=''){const widget=$('#hp-widget'),value=$('#hp-value'),fill=$('#hp-fill');if(!widget||!value||!fill)return;const percent=Math.max(0,currentHP/maxHP*100);value.textContent=currentHP;fill.style.width=`${percent}%`;widget.classList.toggle('danger',currentHP<=20);if(effect){widget.classList.remove(effect);void widget.offsetWidth;widget.classList.add(effect)}}
function showHpRecovery(amount){const notice=$('#hp-recover');if(!notice)return;clearTimeout(notice.timer);notice.textContent=`RECOVER +${amount}`;notice.hidden=false;notice.classList.remove('show');void notice.offsetWidth;notice.classList.add('show');notice.timer=setTimeout(()=>{notice.hidden=true;notice.classList.remove('show')},620)}
function endForHpDepletion(){if(!playing)return;const max=getChartMaximums(chart)?.maxScore||0,rate=max?score/max:0;finalizeRun({outcome:'gameOver',score,rate,maxCombo,judgements:counts,hp:currentHP});playing=false;cancelAnimationFrame(raf);audio.pause();pendingInput=null;nodes.forEach(n=>n.remove());nodes.clear();document.querySelectorAll('.hit-burst,.lane-flash,.hit-beam,.hit-impact,.note-impact-strip,.judge-wave').forEach(n=>n.remove());renderPlayResult('gameOver',rate,max,audio.currentTime)}
function changeHP(amount){if(!playing&&amount<0)return false;const before=currentHP;currentHP=Math.max(0,Math.min(maxHP,currentHP+amount));updateHpUI(amount<0?'hp-hit':amount>0&&currentHP>before?'hp-restored':'');if(currentHP===0){endForHpDepletion();return true}return false}
function applyMissDamage(){return changeHP(-(HP_RULES.missDamage[diffs[di]]||0))}
