function reset(){score=combo=maxCombo=0;maxHP=HP_RULES.maxHP;currentHP=maxHP;lastRecoveryCombo=0;pendingInput=null;activeHolds.clear();heldLanes.clear();resultLog=[];loggedComboMilestones.clear();counts={PERFECT:0,GREAT:0,GOOD:0,MISS:0};nodes.clear();lanes.querySelectorAll('.note').forEach(n=>n.remove());document.querySelectorAll('#game .hit-burst,#game .lane-flash,#game .hit-beam,#game .hit-impact,#game .note-impact-strip,#game .judge-wave').forEach(n=>n.remove());clearAudioVisualizer();hud();updateHpUI()}
