function formatResultTime(seconds){if(!Number.isFinite(seconds)||seconds<0)return '--:--';const whole=Math.floor(seconds);return `${Math.floor(whole/60)}:${String(whole%60).padStart(2,'0')}`}
function resultComment(outcome){if(currentRun?.autoPlay)return 'AUTO PLAY';if(outcome==='gameOver')return 'Keep Trying!';const judged=counts.PERFECT+counts.GREAT+counts.GOOD+counts.MISS;if(judged>0&&counts.MISS===0&&counts.GOOD===0&&counts.GREAT===0)return 'PERFECT!';if(judged>0&&counts.MISS===0)return 'FULL COMBO!';return 'Nice Play!'}
