function move(n){const cardCount=songs.length;si=(si+n+cardCount)%cardCount;renderSelect()}function returnToTitleFromSelect(){show('title')}function returnToTitleFromBonus(){show('title')}
document.addEventListener('click',e=>{const card=e.target.closest?.('[data-song-card-index]');if(!card||screen!=='select')return;const index=Number(card.dataset.songCardIndex);if(index===si)show('difficulty');else if(Number.isInteger(index)&&index>=0&&index<songs.length){si=index;renderSelect()}});
window.addEventListener?.('resize',()=>{if(screen!=='select')return;cancelAnimationFrame(selectCenterFrame);selectCenterFrame=requestAnimationFrame(()=>centerSelectedSongCard('auto'))});
function key(e){if(e.repeat)return;if(screen==='result'){if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();resultSelectionIndex=(resultSelectionIndex+(e.key==='ArrowLeft'?-1:1)+3)%3;renderResultSelection()}else if(e.key==='Enter'){e.preventDefault();document.querySelectorAll('#result-screen .result-actions button')[resultSelectionIndex]?.click()}return}if(screen==='bonus'){if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();moveBonus(e.key==='ArrowLeft'?-1:1)}else if(e.key==='Escape'){e.preventDefault();returnToTitleFromBonus()}return}if(screen==='title'&&hasBonusUnlocked()&&(e.key==='ArrowUp'||e.key==='ArrowDown')){e.preventDefault();titleSelectionIndex=titleSelectionIndex?0:1;renderTitle();return}if(screen==='play'){let l=keys.indexOf(e.key.toLowerCase());if(l>=0){e.preventDefault();queueManualInput(l)}return}if(screen==='select'&&e.key==='Enter'&&e.target.closest?.('[data-action="select-title"]')){e.preventDefault();returnToTitleFromSelect();return}if(e.key==='Enter'){if(screen==='title')show(titleSelectionIndex===1&&hasBonusUnlocked()?'bonus':'select');else if(screen==='select')show('difficulty');else if(screen==='difficulty')startGame();else if(screen==='result'&&!e.target.closest?.('.result-actions'))show('select');else if(screen==='gameover')show('title')}if(e.key==='Escape'){if(screen==='select')returnToTitleFromSelect();if(screen==='difficulty')show('select')}if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();let n=e.key==='ArrowLeft'?-1:1;if(screen==='select')move(e.key==='ArrowLeft'||e.key==='ArrowUp'?-1:1);if(screen==='difficulty'){if(e.key==='ArrowDown')difficultySelectionRow=1;else if(e.key==='ArrowUp')difficultySelectionRow=0;else if(difficultySelectionRow===0)di=(di+n+3)%3;else autoPlay=n>0;renderDifficulty()}}}
function pause(){if(!playing||$('#pause-ui'))return;playing=false;audio.pause();pendingInput=null;cancelAnimationFrame(raf);const p=document.createElement('div');p.id='pause-ui';p.innerHTML='<h1>PAUSED</h1><button id="pause-continue">RESUME</button><button id="pause-retry">RETRY</button><button id="pause-quit">TITLE</button>';$('#play-screen').append(p);pauseSelectedIndex=0;renderPauseSelection();$('#pause-continue').onclick=()=>{p.remove();beginCountdown(()=>{playing=true;audio.play().then(render).catch(()=>{playing=false;show('title')})})};$('#pause-retry').onclick=()=>{p.remove();playing=false;currentRun=null;audio.pause();audio.currentTime=0;pendingInput=null;cancelAnimationFrame(raf);nodes.forEach(n=>n.remove());nodes.clear();document.querySelectorAll('.hit-burst,.lane-flash,.hit-beam,.hit-impact,.note-impact-strip,.judge-wave').forEach(n=>n.remove());startGame()};$('#pause-quit').onclick=()=>{p.remove();playing=false;currentRun=null;audio.pause();audio.currentTime=0;pendingInput=null;cancelAnimationFrame(raf);nodes.forEach(n=>n.remove());nodes.clear();document.querySelectorAll('.hit-burst,.lane-flash,.hit-beam,.hit-impact,.note-impact-strip,.judge-wave').forEach(n=>n.remove());show('title')}}document.addEventListener('keydown',key);document.addEventListener('keyup',e=>{const lane=keys.indexOf(e.key.toLowerCase());if(lane>=0)releaseManualInput(lane)});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&screen==='play')pause()});document.addEventListener('click',e=>{let a=e.target.closest?.('[data-action]')?.dataset.action;if(a==='mobile-pause'&&screen==='play')pause();if(a==='title-start')show('select');if(a==='select-title'&&screen==='select')returnToTitleFromSelect();if(a==='bonus-title'&&screen==='bonus')returnToTitleFromBonus();if(a==='bonus-track'&&hasBonusUnlocked())show('bonus');if(a==='bonus-prev')moveBonus(-1);if(a==='bonus-next')moveBonus(1);if(screen==='result'&&a==='result-retry')startGame();if(screen==='result'&&a==='result-select')show('select');if(screen==='result'&&a==='result-home')show('title');if(a==='gameover-title')show('title')});
window.rhythmGameBridge=Object.freeze({
  getScreen:()=>screen,
  isPlaying:()=>playing,
  isPaused:()=>!!$('#pause-ui'),
  getCurrentRun:()=>currentRun,
  onScreenChange:listener=>gameEvents.screen.push(listener),
  onRunStart:listener=>gameEvents.runStart.push(listener),
  completePlayResult,
  createDefaultSave,
  replaceSaveData:value=>{saveData=value},
  getDifficultyRecord,
  saveGame,
  show,
  ensureAudioContext:ensurePerfectAudio,
  renderFrameAt,
  getPromoCaptureState:()=>({song,chart,difficulty:diffs[di],screen,playing})
});
init();
